INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q266','nism-10a-z0','A monthly SIP of ₹7,000 earns 10% p.a. (monthly compounding, instalments at month-end) for 3 years. The maturity value is approximately:','["₹2,52,000","₹2,48,602","₹2,77,200","₹2,92,473"]',3,'FV = P × [((1 + r)^m − 1) ÷ r], r = i ÷ 12.',266) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
