INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q269','nism-10a-z0','A goal of ₹48,00,000 is needed in 15 years. At 11% p.a. return, the lump sum to invest today is approximately:','["₹11,13,575","₹22,96,603","₹10,03,221","₹18,11,321"]',2,'PV = FV ÷ (1 + i)^n.',269) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
